	"github.com/onsi/ginkgo/v2"

	"github.com/fatedier/frp/pkg/transport"
	"github.com/fatedier/frp/test/e2e/framework"
	"github.com/fatedier/frp/test/e2e/framework/consts"
	"github.com/fatedier/frp/test/e2e/mock/server/httpserver"
	"github.com/fatedier/frp/test/e2e/mock/server/streamserver"
	"github.com/fatedier/frp/test/e2e/pkg/port"
	"github.com/fatedier/frp/test/e2e/pkg/request"
)

var _ = ginkgo.Describe("[Feature: Basic]", func() {
	f := framework.NewDefaultFramework()

	ginkgo.Describe("TCP && UDP", func() {
		types := []string{"tcp", "udp"}
		for _, t := range types {
			proxyType := t
			ginkgo.It(fmt.Sprintf("Expose a %s echo server", strings.ToUpper(proxyType)), func() {
				serverConf := consts.DefaultServerConfig
				var clientConf strings.Builder
				clientConf.WriteString(consts.DefaultClientConfig)

				localPortName := ""
				protocol := "tcp"
				switch proxyType {
				case "tcp":
					localPortName = framework.TCPEchoServerPort
					protocol = "tcp"
				case "udp":
					localPortName = framework.UDPEchoServerPort
					protocol = "udp"
				}
				getProxyConf := func(proxyName string, portName string, extra string) string {
					return fmt.Sprintf(`
				[[proxies]]
				name = "%s"
				type = "%s"
				localPort = {{ .%s }}
				remotePort = {{ .%s }}
				`+extra, proxyName, proxyType, localPortName, portName)
				}

				tests := []struct {
					proxyName   string
					portName    string
					extraConfig string
				}{
					{
						proxyName: "normal",
						portName:  port.GenName("Normal"),
					},
					{
						proxyName:   "with-encryption",
						portName:    port.GenName("WithEncryption"),
						extraConfig: "transport.useEncryption = true",
					},
					{
						proxyName:   "with-compression",
						portName:    port.GenName("WithCompression"),
						extraConfig: "transport.useCompression = true",
					},
					{
						proxyName: "with-encryption-and-compression",
						portName:  port.GenName("WithEncryptionAndCompression"),
						extraConfig: `
						transport.useEncryption = true
						transport.useCompression = true
						`,
					},
				}

				// build all client config
				for _, test := range tests {
					clientConf.WriteString(getProxyConf(test.proxyName, test.portName, test.extraConfig) + "\n")
				}
				// run frps and frpc
				f.RunProcesses(serverConf, []string{clientConf.String()})

				for _, test := range tests {
					framework.NewRequestExpect(f).
						Protocol(protocol).
						PortName(test.portName).
						Explain(test.proxyName).
						Ensure()
				}
			})
		}
	})

	ginkgo.Describe("HTTP", func() {
		ginkgo.It("proxy to HTTP server", func() {
			serverConf := consts.DefaultServerConfig
			vhostHTTPPort := f.AllocPort()
			serverConf += fmt.Sprintf(`
			vhostHTTPPort = %d
			`, vhostHTTPPort)

			var clientConf strings.Builder
			clientConf.WriteString(consts.DefaultClientConfig)

			getProxyConf := func(proxyName string, customDomains string, extra string) string {
				return fmt.Sprintf(`
				[[proxies]]
				name = "%s"
				type = "http"
				localPort = {{ .%s }}
				customDomains = %s
				`+extra, proxyName, framework.HTTPSimpleServerPort, customDomains)
			}

			tests := []struct {
			serverPort = %d
			loginFailExit = false
			transport.protocol = "wss"
			transport.wireProtocol = "v2"
			log.level = "trace"
			`, wssPort),
			client2: fmt.Sprintf(`
			[[proxies]]
			name = "wss2ws"
			type = "tcp"
			remotePort = %d
			[proxies.plugin]
			type = "https2http"
			localAddr = "127.0.0.1:{{ .%s }}"
			`, wssPort, consts.PortServerName),
			testDelay: 10 * time.Second,
		})
	})

	for _, tc := range []struct {
		name      string
		transport string
	}{
		{name: "plain"},
		{name: "aes-cfb", transport: "transport.useEncryption = true"},
		{name: "snappy", transport: "transport.useCompression = true"},
		{name: "snappy and aes-cfb", transport: "transport.useEncryption = true\ntransport.useCompression = true"},
		{name: "limiter", transport: "transport.bandwidthLimit = \"1MB\""},
	} {
		ginkgo.It(tc.name, func() {
			serverConf := consts.DefaultServerConfig
			udpPortName := port.GenName("BinaryUDPPacket")
			clientConf := consts.DefaultClientConfig + fmt.Sprintf(`
			transport.wireProtocol = "v2"

			[[proxies]]
			name = "udp"
			type = "udp"
			localPort = {{ .%s }}
			remotePort = {{ .%s }}
			%s
			`, framework.UDPEchoServerPort, udpPortName, tc.transport)

			f.RunProcesses(serverConf, []string{clientConf})
			framework.NewRequestExpect(f).Protocol("udp").PortName(udpPortName).Ensure()
		})
	}
})

