func TestManagerNewConnCarriesWireProtocolAndUDPPacketCodec(t *testing.T) {
	vm := NewManager()
	listener, err := vm.Listen("sudp", "secret", []string{"*"})
	require.NoError(t, err)
	defer listener.Close()

	client, server := net.Pipe()
	defer client.Close()
	defer server.Close()

