	require.True(t, message.AdaptiveCompression)
	require.Equal(t, "lossy", message.NetworkProfile)

	var decoded ProxyBaseConfig
	decoded.UnmarshalFromMsg(&message)
	require.Equal(t, base.Transport, decoded.Transport)
}

