	if len(sample) > policy.sampleBytes {
		sample = sample[:policy.sampleBytes]
	}
	if len(sample) == 0 {
		return false
	}

	var seen [256]bool
	distinct := 0
	for _, c := range sample {
		if !seen[c] {
			seen[c] = true
			distinct++
		}
	}
	return distinct <= policy.maxDistinct
}

func maskedCRC(b []byte) uint32 {
	c := crc32.Update(0, snappyCRCTable, b)
